"}],"request_feedback":true,"id":"d69fcaad880b4bf8bc96e5eb8949d8b4","name":"Confirm NeedIt Type","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"secure":false},{"type":"ReferenceChoiceInputPrompt","mode":"external","id":"b27cc9864d3540ad959de996f82f4f5e","name":"NeedIt List","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false,"variable_id":"8c0c730882a34a82b86d089ab3503342","message":{"type":"String","mode":"string","value":"gs.getMessageLang("Select a NeedIt record to view.", vaContext.getRequesterLang())"},"request_feedback":false,"skippable":{"type":"Applicability","mode":"script","value":"false"},"skipreprompt":{"type":"Applicability","mode":"script","value":"false"},"nlu_entity_binding":{"type":"NLUEntityBinding","allow_text_input":false,"use_confirmation_prompt":true},"expression_mode":"script","script":"(function execute(table) {
 /* Code your glide record query logic here. For example:

 var options = [];
 var gr = new GlideRecordSecure(table);
 gr.addEncodedQuery('active=true^numberSTARTSWITHINC001001');
 gr.setLimit(10);
 gr.query();
 while(gr.next()) {
 options.push({ 'value': gr.getUniqueValue(), 'label': gr.getValue('short_description') });
 }
 return options;
 */

 //var options = []; // add options here...
 //return options;
 // Initialize an array for the list of NeedIt records to show
 var options = [];

 // Query the table selected in the Table field for active records with the 
 // u_request_type selected in the NeedIt Type node where the user is the 
 // u_requested_for. Order the results by the When needed value.
 var grNI = new GlideRecord(table);
 grNI.addQuery('u_request_type',vaInputs.needit_type.getValue());
 grNI.addQuery('active','true');
 grNI.addQuery('u_requested_for',vaInputs.user);
 grNI.orderBy('u_when_needed');
 grNI.query();

 // Push a value and label pair to the array for each record the query returns.
 // The value is the unique value. The label is the number, u_when_needed, and // short_description values for the NeedIt record.
 while(grNI.next()) {
 options.push({ 'value': grNI.getUniqueValue(), 'label': grNI.getValue('number') + " (" + grNI.getDisplayValue('u_when_needed') + "): " + grNI.getValue('short_description') });
 }

 // Return the array
 return options;
})(table)
